"""
Backend abstraction layer for pandas & polars dual support.
"""

from __future__ import annotations

import logging
from typing import Any, Callable, Literal, Optional, Union

import numpy as np

try:
    import polars as pl
    _POLARS_AVAILABLE = True
except ImportError:
    _POLARS_AVAILABLE = False

import pandas as pd
from scipy import stats as scipy_stats

logger = logging.getLogger(__name__)

BackendType = Literal["pandas", "polars"]

_POLARS_IMPORT_ERROR = (
    "Backend 'polars' requires the polars package. "
    "Install with: pip install polars"
)


def _require_polars() -> None:
    if not _POLARS_AVAILABLE:
        raise ImportError(_POLARS_IMPORT_ERROR)


def _detect_source(data: Any) -> tuple[Any, BackendType]:
    """Return raw dataframe and detected backend type from arbitrary input."""
    if isinstance(data, Backend):
        return data._data, data._type
    if isinstance(data, pd.DataFrame):
        return data, "pandas"
    if _POLARS_AVAILABLE and isinstance(data, pl.DataFrame):
        return data, "polars"
    return pd.DataFrame(data), "pandas"


def _convert_to_backend(raw_data: Any, target: BackendType) -> Any:
    """Convert raw data to the requested backend dataframe type."""
    if target == "pandas":
        if isinstance(raw_data, pd.DataFrame):
            return raw_data
        if _POLARS_AVAILABLE and isinstance(raw_data, pl.DataFrame):
            return raw_data.to_pandas()
        return pd.DataFrame(raw_data)

    _require_polars()
    if _POLARS_AVAILABLE and isinstance(raw_data, pl.DataFrame):
        return raw_data
    if isinstance(raw_data, pd.DataFrame):
        return pl.from_pandas(raw_data)
    return pl.from_pandas(pd.DataFrame(raw_data))


def resolve_backend(data: Any, backend: BackendType | None = None) -> "Backend":
    """
    Resolve input data to a Backend instance.

    When ``backend`` is None, auto-detect from input type.
    When explicit, convert to the requested engine.
    """
    raw_data, detected = _detect_source(data)
    target: BackendType = backend if backend is not None else detected

    if target == "polars":
        _require_polars()

    inst = Backend.__new__(Backend)
    inst._type = target
    inst._data = _convert_to_backend(raw_data, target)
    inst._col_cache: dict[str, np.ndarray] = {}
    return inst


class Backend:
    """Unified wrapper for pandas and polars DataFrames."""

    def __init__(self, data: Any, backend: BackendType | None = None):
        resolved = resolve_backend(data, backend)
        self._type = resolved._type
        self._data = resolved._data
        self._col_cache: dict[str, np.ndarray] = {}

    def _invalidate_cache(self, column: Optional[str] = None) -> None:
        """Clear cached numpy columns (all or one)."""
        if column is None:
            self._col_cache.clear()
        else:
            self._col_cache.pop(column, None)

    @property
    def type(self) -> BackendType:
        return self._type

    @property
    def df(self):
        return self._data

    @df.setter
    def df(self, value) -> None:
        self._data = value
        self._invalidate_cache()

    def to_pandas(self) -> pd.DataFrame:
        if self._type == "polars":
            return self._data.to_pandas()
        return self._data

    def to_polars(self):
        """Return data as a polars DataFrame."""
        if self._type == "polars":
            return self._data
        _require_polars()
        return pl.from_pandas(self._data)

    def convert_to(self, backend: BackendType) -> "Backend":
        """Return a new Backend using the requested engine."""
        return resolve_backend(self, backend=backend)

    def is_pandas(self) -> bool:
        return self._type == "pandas"

    def is_polars(self) -> bool:
        return self._type == "polars"

    # ── shape ──────────────────────────────────────────────────────────

    @property
    def shape(self) -> tuple[int, int]:
        return self._data.shape

    @property
    def columns(self) -> list[str]:
        return self._data.columns

    # ── column dtypes ──────────────────────────────────────────────────

    dtypes_map = {
        "number": {np.dtype("int64"), np.dtype("int32"), np.dtype("int16"), np.dtype("int8"),
                   np.dtype("uint64"), np.dtype("uint32"), np.dtype("uint16"), np.dtype("uint8"),
                   np.dtype("float64"), np.dtype("float32")},
        "category": {np.dtype("object"), np.dtype("str_")},
    }

    def numeric_columns(self) -> list[str]:
        if self._type == "pandas":
            return self._data.select_dtypes(include=["number"]).columns.tolist()
        return [c for c in self._data.columns
                if self._data[c].dtype in (pl.Float64, pl.Float32, pl.Int64, pl.Int32,
                                           pl.Int16, pl.Int8, pl.UInt64, pl.UInt32,
                                           pl.UInt16, pl.UInt8)]

    def categorical_columns(self) -> list[str]:
        if self._type == "pandas":
            return self._data.select_dtypes(include=["object", "category"]).columns.tolist()
        return [c for c in self._data.columns
                if self._data[c].dtype in (pl.Utf8, pl.Categorical)]

    # ── column access ──────────────────────────────────────────────────

    def col(self, name: str) -> pd.Series:
        """Return a column as a pandas Series (always)."""
        if self._type == "polars":
            return self._data[name].to_pandas()
        return self._data[name]

    def col_raw(self, name: str):
        """Return a column in its native backend type."""
        return self._data[name]

    def col_numpy(self, name: str) -> np.ndarray:
        """Return column as float-compatible numpy array (cached)."""
        cached = self._col_cache.get(name)
        if cached is not None:
            return cached
        if self._type == "polars":
            arr = self._data[name].to_numpy()
        else:
            arr = self._data[name].to_numpy()
        self._col_cache[name] = arr
        return arr

    def set_col(self, name: str, values) -> None:
        self._data[name] = values
        self._invalidate_cache(name)

    # ── missing values ─────────────────────────────────────────────────

    def isna_sum(self) -> pd.Series:
        if self._type == "polars":
            return self._data.null_count().to_pandas().iloc[0]
        return self._data.isna().sum()

    def dropna(self, subset: Optional[list[str]] = None, how: str = "any"):
        if self._type == "polars":
            self._data = self._data.drop_nulls(subset=subset)
        else:
            self._data = self._data.dropna(subset=subset, how=how)
        self._invalidate_cache()

    def fillna(self, value: Any = None, method: Optional[str] = None, columns: Optional[list[str]] = None):
        if self._type == "polars":
            if method == "ffill":
                self._data = self._data.fill_null(strategy="forward")
            elif method == "bfill":
                self._data = self._data.fill_null(strategy="backward")
            else:
                self._data = self._data.fill_null(value=value)
        else:
            if columns:
                for c in columns:
                    self._data[c] = self._data[c].fillna(value=value, method=method)
            else:
                self._data = self._data.fillna(value=value, method=method)
        self._invalidate_cache()

    # ── descriptive stats ──────────────────────────────────────────────
    #
    # All univariate statistics drop NaN values before computing, so results
    # are consistent with ``column_summary()``. Dispersion statistics default
    # to the sample convention (``ddof=1``).

    def col_clean(self, name: str) -> np.ndarray:
        """Return column as a float numpy array with NaN values removed."""
        vals = np.asarray(self.col_numpy(name), dtype=float)
        return vals[~np.isnan(vals)]

    def count(self, column: str) -> int:
        """Number of non-missing observations in the column."""
        return int(len(self.col_clean(column)))

    def n_missing(self, column: str) -> int:
        """Number of missing (NaN) observations in the column."""
        vals = np.asarray(self.col_numpy(column), dtype=float)
        return int(np.isnan(vals).sum())

    def mean(self, column: str) -> float:
        return float(np.mean(self.col_clean(column)))

    def median(self, column: str) -> float:
        return float(np.median(self.col_clean(column)))

    def mode(self, column: str):
        vals = self.col_clean(column)
        mode_result = scipy_stats.mode(vals, keepdims=True)
        return mode_result.mode[0] if hasattr(mode_result.mode, "__len__") else mode_result.mode

    def std(self, column: str, ddof: int = 1) -> float:
        return float(np.std(self.col_clean(column), ddof=ddof))

    def var(self, column: str, ddof: int = 1) -> float:
        return float(np.var(self.col_clean(column), ddof=ddof))

    def skew(self, column: str) -> float:
        vals = self.col_clean(column)
        if len(vals) <= 2:
            return float("nan")
        return float(scipy_stats.skew(vals, bias=False))

    def kurtosis(self, column: str) -> float:
        """Excess (Fisher) kurtosis: a normal distribution has kurtosis 0."""
        vals = self.col_clean(column)
        if len(vals) <= 3:
            return float("nan")
        return float(scipy_stats.kurtosis(vals, bias=False, fisher=True))

    def quantile(self, column: str, q: float) -> float:
        return float(np.quantile(self.col_clean(column), q))

    def min(self, column: str) -> float:
        return float(np.min(self.col_clean(column)))

    def max(self, column: str) -> float:
        return float(np.max(self.col_clean(column)))

    def nunique(self, column: str) -> int:
        if self._type == "polars":
            return self._data[column].n_unique()
        return int(self._data[column].nunique())

    def value_counts(self, column: str, normalize: bool = False):
        if self._type == "polars":
            result = self._data[column].value_counts()
            if normalize:
                total = result["count"].sum()
                result = result.with_columns((pl.col("count") / total).alias("count"))
            return result.to_pandas()
        return self._data[column].value_counts(normalize=normalize)

    # ── relationships ──────────────────────────────────────────────────

    def corr(self, method: str = "pearson"):
        numeric_cols = self.numeric_columns()
        if not numeric_cols:
            return pd.DataFrame()
        if self._type == "polars":
            data_numeric = self._data.select(numeric_cols)
            # Prefer native polars corr when available (pearson only in older versions).
            if method == "pearson" and hasattr(data_numeric, "corr"):
                try:
                    corr_pl = data_numeric.corr()
                    return corr_pl.to_pandas().set_index(
                        pd.Index(numeric_cols, name=None)
                    ) if "column" not in corr_pl.columns else (
                        corr_pl.to_pandas().set_index("column")
                    )
                except Exception:
                    pass
            return data_numeric.to_pandas().corr(method=method)
        return self._data[numeric_cols].corr(method=method)

    def cov(self):
        numeric_cols = self.numeric_columns()
        if not numeric_cols:
            return pd.DataFrame()
        if self._type == "polars":
            pdf = self._data.select(numeric_cols).to_pandas()
            return pdf.cov()
        return self._data[numeric_cols].cov()

    def column_summary(
        self,
        columns: Optional[list[str]] = None,
        percentiles: Optional[list[float]] = None,
    ) -> dict[str, dict[str, float]]:
        """
        Fast per-column descriptive summary using a single numpy pass per column.

        Returns a dict keyed by column name with count/mean/median/mode/std/var/
        min/max/quartiles/iqr/skew/kurtosis (and optional custom percentiles).
        """
        cols = columns or self.numeric_columns()
        pcts = percentiles if percentiles is not None else [0.25, 0.75]
        results: dict[str, dict[str, float]] = {}

        for col in cols:
            raw = np.asarray(self.col_numpy(col), dtype=float)
            vals = raw[~np.isnan(raw)]
            n = len(vals)
            n_miss = len(raw) - n
            if n == 0:
                results[col] = {
                    "count": 0,
                    "n_missing": n_miss,
                    "mean": np.nan,
                    "median": np.nan,
                    "mode": np.nan,
                    "std": np.nan,
                    "variance": np.nan,
                    "min": np.nan,
                    "q1": np.nan,
                    "q3": np.nan,
                    "max": np.nan,
                    "iqr": np.nan,
                    "skewness": np.nan,
                    "kurtosis": np.nan,
                }
                continue

            q_vals = np.quantile(vals, pcts)
            q_map = {f"p{int(p * 100)}": float(q) for p, q in zip(pcts, q_vals)}
            q1 = float(np.quantile(vals, 0.25))
            q3 = float(np.quantile(vals, 0.75))
            mode_result = scipy_stats.mode(vals, keepdims=True)
            mode_val = mode_result.mode[0] if hasattr(mode_result.mode, "__len__") else mode_result.mode

            entry = {
                "count": int(n),
                "n_missing": n_miss,
                "mean": float(np.mean(vals)),
                "median": float(np.median(vals)),
                "mode": mode_val if not isinstance(mode_val, (float, np.floating)) else float(mode_val),
                "std": float(np.std(vals, ddof=1)) if n > 1 else np.nan,
                "variance": float(np.var(vals, ddof=1)) if n > 1 else np.nan,
                "min": float(np.min(vals)),
                "q1": q1,
                "q3": q3,
                "max": float(np.max(vals)),
                "iqr": q3 - q1,
                "skewness": float(scipy_stats.skew(vals, bias=False)) if n > 2 else np.nan,
                "kurtosis": float(scipy_stats.kurtosis(vals, bias=False, fisher=True)) if n > 3 else np.nan,
            }
            entry.update(q_map)
            results[col] = entry

        return results

    def crosstab(self, index, columns, margins: bool = True, normalize: bool = False):
        if self._type == "polars":
            pdf = self._data.to_pandas()
            return pd.crosstab(pdf[index], pdf[columns], margins=margins, normalize=normalize)
        return pd.crosstab(self._data[index], self._data[columns], margins=margins, normalize=normalize)

    # ── reshaping ──────────────────────────────────────────────────────

    def rename(self, mapping: dict[str, str]):
        if self._type == "polars":
            self._data = self._data.rename(mapping)
        else:
            self._data = self._data.rename(columns=mapping)
        self._invalidate_cache()

    def astype(self, column: str, dtype):
        if self._type == "polars":
            self._data = self._data.with_columns(self._data[column].cast(dtype))
        else:
            self._data[column] = self._data[column].astype(dtype)
        self._invalidate_cache(column)

    def filter_by_mask(self, mask):
        if self._type == "polars":
            self._data = self._data.filter(mask)
        else:
            self._data = self._data[mask]
        self._invalidate_cache()

    def head(self, n: int = 5):
        if self._type == "polars":
            return self._data.head(n).to_pandas()
        return self._data.head(n)

    def select_columns(self, columns: list[str]):
        if self._type == "polars":
            self._data = self._data.select(columns)
        else:
            self._data = self._data[columns]
        self._invalidate_cache()

    # ── grouping ───────────────────────────────────────────────────────

    def groupby(self, by: Union[str, list[str]], agg: dict[str, str]):
        """Group by and aggregate. Returns a pandas DataFrame."""
        if self._type == "polars":
            return self._data.group_by(by).agg([getattr(pl.col(k), v)() if hasattr(pl.col(k), v) else pl.col(k).alias(f"{k}_{v}") for k, v in agg.items()]).to_pandas()
        result = self._data.groupby(by).agg(agg)
        if isinstance(result.columns, pd.MultiIndex):
            result.columns = [f"{k}_{v}" if v else k for k, v in result.columns]
        return result.reset_index()

    # ── copy ───────────────────────────────────────────────────────────

    def copy(self) -> Backend:
        if self._type == "polars":
            return Backend(self._data.clone(), backend=self._type)
        return Backend(self._data.copy(), backend=self._type)

    def __repr__(self) -> str:
        return f"Backend(type={self._type}, shape={self.shape})"

from __future__ import annotations

import io
import logging
import pkgutil
from pathlib import Path
from typing import Any, List, Literal, Optional, Tuple, Union

import numpy as np
import pandas as pd
from numpy.typing import NDArray

logger = logging.getLogger(__name__)

try:
    import polars as pl
    _POLARS_AVAILABLE = True
except ImportError:
    _POLARS_AVAILABLE = False

_SUPPORTED_BACKENDS = {"pandas", "polars"} if _POLARS_AVAILABLE else {"pandas"}
_SUPPORTED_EXTENSIONS = {".csv", ".parquet", ".xlsx", ".xls", ".json"}
_BUNDLED_DATASETS = ("iris.csv", "penguins.csv", "titanic.csv")


def _validate_columns(
    df: pd.DataFrame,
    X_columns: List[str],
    y_column: str,
) -> None:
    columns = set(df.columns)
    missing = set(X_columns + [y_column]) - columns
    if missing:
        raise ValueError(f"Columns not found in dataset: {missing}")


def _X_y(
    df: Union[pd.DataFrame, Any],
    X_columns: List[str],
    y_column: str,
) -> Tuple[NDArray, NDArray]:
    if _POLARS_AVAILABLE and isinstance(df, pl.DataFrame):
        pdf = df.to_pandas()
    else:
        pdf = df
    _validate_columns(pdf, X_columns, y_column)
    X = pdf[X_columns].to_numpy()
    y = pdf[y_column].to_numpy().ravel()
    return X, y


def _read_file(
    buffer_or_path,
    ext: str,
    backend: str,
    sep: str,
):
    if backend == "pandas":
        if ext == ".csv":
            return pd.read_csv(buffer_or_path, sep=sep)
        if ext == ".parquet":
            return pd.read_parquet(buffer_or_path)
        if ext in {".xlsx", ".xls"}:
            return pd.read_excel(buffer_or_path)
        if ext == ".json":
            return pd.read_json(buffer_or_path)

    if backend == "polars":
        if not _POLARS_AVAILABLE:
            raise ImportError("polars is required for backend='polars'. Install with: pip install polars")
        if ext == ".csv":
            return pl.read_csv(buffer_or_path, separator=sep)
        if ext == ".parquet":
            return pl.read_parquet(buffer_or_path)
        if ext in {".xlsx", ".xls"}:
            return pl.read_excel(buffer_or_path)
        if ext == ".json":
            return pl.read_json(buffer_or_path)

    raise ValueError(f"Extension '{ext}' not supported for backend '{backend}'.")


def load_dataset(
    name: str,
    backend: str = "pandas",
    return_X_y: Optional[Tuple[List[str], str]] = None,
    sep: str = ",",
) -> Union[pd.DataFrame, Any, Tuple[NDArray, NDArray]]:
    """
    Load a bundled dataset or a local file.

    Bundled datasets: ``iris.csv``, ``penguins.csv``, ``titanic.csv``.

    Parameters
    ----------
    name : str
        File name (e.g. ``iris.csv``) or a local path.
    backend : {'pandas', 'polars'}, default 'pandas'
        DataFrame engine.
    return_X_y : tuple of (list of str, str), optional
        When given, returns (X, y) numpy arrays for the listed feature
        columns and target column.
    sep : str, default ','
        Separator for CSV files.

    Returns
    -------
    DataFrame or (X, y)
    """
    if backend not in _SUPPORTED_BACKENDS:
        if backend == "polars" and not _POLARS_AVAILABLE:
            raise ImportError(
                "Backend 'polars' requires the polars package. "
                "Install with: pip install polars"
            )
        raise ValueError(
            f"Backend '{backend}' not supported. "
            f"Use one of {_SUPPORTED_BACKENDS}."
        )

    path = Path(name)
    resource_name = path.name
    ext = path.suffix.lower()

    if ext == "":
        resource_name = f"{name}.csv" if not name.endswith(".csv") else name
        ext = ".csv"

    if ext not in _SUPPORTED_EXTENSIONS:
        raise ValueError(
            f"Extension '{ext}' not supported. "
            f"Supported: {_SUPPORTED_EXTENSIONS}"
        )

    df = None

    try:
        data_bytes = pkgutil.get_data("statslibx.datasets", resource_name)

        if data_bytes is not None:
            buffer = io.BytesIO(data_bytes)
            df = _read_file(buffer, ext, backend, sep)
    except FileNotFoundError:
        pass

    if df is None:
        if not path.exists():
            raise FileNotFoundError(
                f"Dataset '{name}' not found in statslibx.datasets "
                f"nor as a local path."
            )
        df = _read_file(path, ext, backend, sep)

    if return_X_y is not None:
        X_columns, y_column = return_X_y
        return _X_y(df, X_columns, y_column)

    return df


def load_iris(
    backend: str = "pandas",
    return_X_y: Optional[Tuple[List[str], str]] = None,
):
    return load_dataset("iris.csv", backend=backend, return_X_y=return_X_y)


def load_penguins(
    backend: str = "pandas",
    return_X_y: Optional[Tuple[List[str], str]] = None,
):
    return load_dataset("penguins.csv", backend=backend, return_X_y=return_X_y)


def generate_dataset(
    n_rows: int,
    schema: dict[str, Any],
    seed: Optional[int] = None,
    save: bool = False,
    filename: Optional[str] = None,
) -> pd.DataFrame:
    """
    Generate a synthetic dataset from a schema definition.

    Parameters
    ----------
    n_rows : int
        Number of rows to generate.
    schema : dict[str, Any]
        Column definitions. Each key is a column name; each value is a dict with:
        - ``dist``: distribution type (normal, uniform, exponential, lognormal,
          poisson, binomial, categorical)
        - ``type`` (optional, default ``"float"``): ``"float"`` or ``"int"``
        - ``round`` (optional, default ``2``): decimal places to round
        - Distribution-specific parameters (e.g. ``mean``, ``std``, ``low``, ``high``,
          ``lam``, ``n``, ``p``, ``choices``)
    seed : int, optional
        Random seed for reproducibility. If ``None``, the output is
        non-deterministic.
    save : bool, default False
        Whether to save the dataset to CSV.
    filename : str, optional
        Output filename (without extension). Ignored if ``save`` is False.

    Returns
    -------
    pd.DataFrame
        Generated synthetic dataset.
    """
    rng = np.random.default_rng(seed)

    if not isinstance(schema, dict):
        raise TypeError("schema must be a dictionary")

    data: dict[str, Any] = {}

    for col, config in schema.items():
        if "dist" not in config:
            raise ValueError(f"Column '{col}' has no 'dist' defined")

        dist = config["dist"]
        dtype = config.get("type", "float")
        nround = config.get("round", 2)

        if dist == "normal":
            values = rng.normal(loc=config.get("mean", 0), scale=config.get("std", 1), size=n_rows)
        elif dist == "uniform":
            values = rng.uniform(low=config.get("low", 0), high=config.get("high", 1), size=n_rows)
        elif dist == "exponential":
            values = rng.exponential(scale=config.get("scale", 1), size=n_rows)
        elif dist == "lognormal":
            values = rng.lognormal(mean=config.get("mean", 0), sigma=config.get("std", 1), size=n_rows)
        elif dist == "poisson":
            values = rng.poisson(lam=config.get("lam", 1), size=n_rows)
        elif dist == "binomial":
            values = rng.binomial(n=config.get("n", 1), p=config.get("p", 0.5), size=n_rows)
        elif dist == "categorical":
            if "choices" not in config:
                raise ValueError(f"'choices' is required for categorical ({col})")
            values = rng.choice(config["choices"], size=n_rows)
            data[col] = values
            continue
        else:
            raise ValueError(f"Unsupported distribution: {dist}")

        if dtype == "int":
            values = np.round(values).astype(int)
        elif dtype == "float":
            values = values.astype(float)
        else:
            raise ValueError(f"Unsupported type: {dtype}")

        if nround > 0:
            values = np.round(values, nround)

        data[col] = values

    df = pd.DataFrame(data)

    if save:
        output_name = f"{filename or 'dataset'}.csv"
        df.to_csv(output_name, index=False)
        logger.info("Dataset saved to %s", output_name)

    return df

"""
Shared formatting helpers for consistent console / markdown / JSON result output.
Internal utility — not a public analysis module.
"""

from __future__ import annotations

import json
from typing import Any, Iterable, Mapping, Optional, Sequence, Union

import numpy as np
import pandas as pd


def format_number(
    x: Any,
    decimals: int = 4,
    scientific: bool = False,
) -> str:
    """Format a numeric value consistently."""
    if x is None:
        return "—"
    try:
        if isinstance(x, (float, int, np.floating, np.integer)):
            val = float(x)
            if np.isnan(val):
                return "NaN"
            if np.isinf(val):
                return "Inf" if val > 0 else "-Inf"
            if scientific:
                return f"{val:.{decimals}e}"
            return f"{val:.{decimals}f}"
    except (TypeError, ValueError):
        pass
    return str(x)


def format_pvalue(p: Any, threshold: float = 0.001, decimals: int = 4) -> str:
    """Format a p-value, using '< 0.001' style for very small values."""
    try:
        val = float(p)
    except (TypeError, ValueError):
        return str(p)
    if np.isnan(val):
        return "NaN"
    if val < threshold:
        return f"< {threshold}"
    return f"{val:.{decimals}f}"


def format_ci(
    lower: Any,
    upper: Any,
    confidence: float = 0.95,
    decimals: int = 4,
) -> str:
    """Format a confidence interval as '[lo, hi] (95%)'."""
    pct = int(round(confidence * 100))
    return (
        f"[{format_number(lower, decimals)}, {format_number(upper, decimals)}] "
        f"({pct}%)"
    )


def format_table(
    records: Sequence[Mapping[str, Any]],
    columns: Optional[Sequence[str]] = None,
    decimals: int = 4,
    max_col_width: int = 24,
) -> str:
    """Render a list of dicts as an ASCII table."""
    if not records:
        return "(empty)"

    cols = list(columns) if columns else list(records[0].keys())
    rows: list[list[str]] = []
    for rec in records:
        row = []
        for c in cols:
            val = rec.get(c, "")
            if isinstance(val, (float, np.floating)):
                row.append(format_number(val, decimals))
            else:
                row.append(str(val))
        rows.append(row)

    widths = []
    for i, c in enumerate(cols):
        content_w = max((len(r[i]) for r in rows), default=0)
        widths.append(min(max(len(str(c)), content_w), max_col_width))

    def _clip(s: str, w: int) -> str:
        return s if len(s) <= w else s[: w - 1] + "…"

    header = " | ".join(_clip(str(c), widths[i]).ljust(widths[i]) for i, c in enumerate(cols))
    sep = "-+-".join("-" * w for w in widths)
    body = [
        " | ".join(_clip(r[i], widths[i]).ljust(widths[i]) for i in range(len(cols)))
        for r in rows
    ]
    return "\n".join([header, sep, *body])


def records_to_markdown(
    records: Sequence[Mapping[str, Any]],
    columns: Optional[Sequence[str]] = None,
    decimals: int = 4,
) -> str:
    """Render records as a GitHub-flavored markdown table."""
    if not records:
        return "_empty_"
    cols = list(columns) if columns else list(records[0].keys())
    header = "| " + " | ".join(str(c) for c in cols) + " |"
    sep = "| " + " | ".join("---" for _ in cols) + " |"
    lines = [header, sep]
    for rec in records:
        cells = []
        for c in cols:
            val = rec.get(c, "")
            if isinstance(val, (float, np.floating)):
                cells.append(format_number(val, decimals))
            else:
                cells.append(str(val))
        lines.append("| " + " | ".join(cells) + " |")
    return "\n".join(lines)


def to_json_safe(obj: Any, decimals: int = 6) -> Any:
    """Convert numpy / pandas objects to JSON-serializable structures."""
    if obj is None:
        return None
    if isinstance(obj, (str, bool, int)):
        return obj
    if isinstance(obj, (float, np.floating)):
        val = float(obj)
        if np.isnan(val) or np.isinf(val):
            return None
        return round(val, decimals)
    if isinstance(obj, (np.integer,)):
        return int(obj)
    if isinstance(obj, np.ndarray):
        return [to_json_safe(x, decimals) for x in obj.tolist()]
    if isinstance(obj, pd.Series):
        return {str(k): to_json_safe(v, decimals) for k, v in obj.items()}
    if isinstance(obj, pd.DataFrame):
        return [to_json_safe(r, decimals) for r in obj.to_dict(orient="records")]
    if isinstance(obj, Mapping):
        return {str(k): to_json_safe(v, decimals) for k, v in obj.items()}
    if isinstance(obj, (list, tuple)):
        return [to_json_safe(x, decimals) for x in obj]
    return str(obj)


def dumps_json(obj: Any, indent: int = 2) -> str:
    """Serialize an object to a JSON string."""
    return json.dumps(to_json_safe(obj), indent=indent, ensure_ascii=False)

from __future__ import annotations

import logging
import warnings
from typing import Any, Dict, List, Optional, Union, Literal

import numpy as np
import pandas as pd

from ..backend import Backend

try:
    import polars as pl
    _POLARS_AVAILABLE = True
except ImportError:
    _POLARS_AVAILABLE = False

logger = logging.getLogger(__name__)


class Preprocessing:
    """
    Data preparation pipeline over a pandas or polars DataFrame.

    Provides inspection (nulls, uniqueness, quality report), cleaning
    (duplicates, missing values, outliers), scaling, dtype conversion
    and column filtering. Most methods mutate the instance in place and
    return ``self`` for fluent chaining.
    """

    def __init__(
        self,
        data,
        backend: Optional[Literal["pandas", "polars"]] = None,
    ):
        """
        Initialize Preprocessing pipeline.

        Parameters
        ----------
        data : pandas DataFrame, polars DataFrame, or array-like
            Input dataset.
        backend : {'pandas', 'polars'}, optional
            Data engine to use. Auto-detects from input type when None.
        """
        self._backend = Backend(data, backend=backend)
        self.data = self._backend.df
        self.columns = list(self._backend.columns)

    @classmethod
    def from_file(
        cls,
        path: str,
        backend: str = "pandas",
        sep: str = ",",
    ) -> "Preprocessing":
        """Load data from a file and return a Preprocessing instance."""
        from ..datasets import load_dataset
        return cls(
            load_dataset(path, backend=backend, sep=sep),
            backend=backend,
        )

    @property
    def backend(self):
        return self._backend.type

    @property
    def backend_engine(self) -> Backend:
        """Return the internal Backend wrapper."""
        return self._backend

    # ------------------------------------------------------------------
    # Internal helpers
    # ------------------------------------------------------------------

    def _is_pandas(self) -> bool:
        return self._backend.is_pandas()

    def _count_nulls(self, column: str) -> int:
        return int(self._backend.isna_sum().get(column, 0))

    def _get_columns(self, columns):
        if columns is None:
            return list(self._backend.columns)
        if isinstance(columns, str):
            return [columns]
        return columns

    # ------------------------------------------------------------------
    # Inspection
    # ------------------------------------------------------------------

    def detect_nulls(
        self,
        columns: Optional[Union[str, List[str]]] = None
    ) -> pd.DataFrame:

        columns = self._get_columns(columns)
        total = self._backend.shape[0]
        null_counts = self._backend.isna_sum()

        rows = []
        for col in columns:
            nulls = int(null_counts.get(col, 0))
            rows.append({
                "column": col,
                "nulls": nulls,
                "non_nulls": total - nulls,
                "null_pct": nulls / total
            })

        return pd.DataFrame(rows)

    def check_uniqueness(self) -> pd.DataFrame:
        rows = []
        for col in self._backend.columns:
            rows.append({
                "column": col,
                "unique_values": self._backend.nunique(col)
            })
        return pd.DataFrame(rows)

    def preview_data(self, n: int = 5):
        return self._backend.head(n)

    # ------------------------------------------------------------------
    # Description
    # ------------------------------------------------------------------

    def describe_numeric(self):
        numeric_cols = self._backend.numeric_columns()
        if not numeric_cols:
            return pd.DataFrame()
        if self._backend.is_pandas():
            return self._backend.df[numeric_cols].describe()
        return self._backend.df.select(numeric_cols).to_pandas().describe()

    def describe_categorical(self):
        cat_cols = self._backend.categorical_columns()
        if not cat_cols:
            return pd.DataFrame()
        if self._backend.is_pandas():
            return self._backend.df[cat_cols].describe()
        return self._backend.df.select(cat_cols).to_pandas().describe()

    # ------------------------------------------------------------------
    # Transformations
    # ------------------------------------------------------------------

    def fill_nulls(
        self,
        fill_with: Any,
        columns: Optional[Union[str, List[str]]] = None
    ):
        columns = self._get_columns(columns)
        self._backend.fillna(value=fill_with, columns=columns)
        self.data = self._backend.df
        return self

    def normalize(self, column: str):
        col = self._backend.col(column)
        normalized = (col - col.min()) / (col.max() - col.min())
        self._backend.set_col(column, normalized.values if hasattr(normalized, 'values') else normalized)
        self.data = self._backend.df
        return self

    def standardize(self, column: str):
        col = self._backend.col(column)
        standardized = (col - col.mean()) / col.std()
        self._backend.set_col(column, standardized.values if hasattr(standardized, 'values') else standardized)
        self.data = self._backend.df
        return self

    # ------------------------------------------------------------------
    # Filtering
    # ------------------------------------------------------------------

    def filter_rows(self, condition):
        if self._backend.is_pandas():
            self._backend.filter_by_mask(condition)
        else:
            self._backend.filter_by_mask(condition)
        self.data = self._backend.df
        return self

    def filter_columns(self, columns: List[str]):
        self._backend.select_columns(columns)
        self.data = self._backend.df
        return self

    def rename_columns(self, mapping: Dict[str, str]):
        self._backend.rename(mapping)
        self.data = self._backend.df
        return self

    # ------------------------------------------------------------------
    # Outliers
    # ------------------------------------------------------------------

    def detect_outliers(
        self,
        column: str,
        method: str = "iqr"
    ) -> pd.DataFrame:

        series = self._backend.col(column)

        if method == "iqr":
            q1 = series.quantile(0.25)
            q3 = series.quantile(0.75)
            iqr = q3 - q1
            mask = (series < q1 - 1.5 * iqr) | (series > q3 + 1.5 * iqr)

        elif method == "zscore":
            z = (series - series.mean()) / series.std()
            mask = z.abs() > 3

        else:
            raise ValueError("method must be 'iqr' or 'zscore'")

        if self._backend.is_pandas():
            outliers = self._backend.df[mask.values]
        else:
            outliers = self._backend.df.filter(mask.values)

        if len(outliers) == 0:
            print(f"No outliers found in column '{column}'")
            return outliers

        return outliers

    # ------------------------------------------------------------------
    # Data Quality Report
    # ------------------------------------------------------------------

    def data_quality(self) -> pd.DataFrame:
        total_rows = self._backend.shape[0]
        null_counts = self._backend.isna_sum()
        rows = []

        for col in self._backend.columns:
            nulls = int(null_counts.get(col, 0))
            unique = self._backend.nunique(col)

            if self._backend.is_pandas():
                dtype = str(self._backend.df[col].dtype)
            else:
                dtype = str(self._backend.df.schema[col])

            rows.append({
                "column": col,
                "dtype": dtype,
                "nulls": nulls,
                "null_pct": nulls / total_rows,
                "unique_values": unique,
                "completeness_pct": 1 - (nulls / total_rows)
            })

        return pd.DataFrame(rows)

    def change_dtypes(
        self,
        columns: Union[List[str], str, None] = None,
        from_type: Optional[str] = None,
        to_type: Optional[str] = None
    ) -> pd.DataFrame:

        data = self._backend.df

        TYPE_MAP = {
            "string": "string",
            "object": "object",
            "int": "int64",
            "float": "float64",
            "int64": "int64",
            "float64": "float64",
            "number": "float64"
        }

        if columns is None:
            columns = list(self._backend.columns)
        elif isinstance(columns, str):
            columns = [columns]

        if to_type and to_type not in TYPE_MAP:
            raise ValueError(f"Unsupported to_type: {to_type}")

        missing_cols = [c for c in columns if c not in self._backend.columns]
        if missing_cols:
            raise ValueError(
                f"Column(s) {missing_cols} do not exist in the DataFrame. "
                f"Available columns: {list(self._backend.columns)}"
            )

        if self._backend.is_pandas():

            for col in columns:

                if from_type is not None:
                    current_type = str(data[col].dtype)
                    if from_type not in current_type:
                        continue

                if to_type is not None:
                    try:
                        if to_type in ["int", "float", "number"]:
                            data[col] = pd.to_numeric(data[col], errors="raise")
                            if to_type == "int":
                                data[col] = data[col].astype("int64")
                        elif to_type == "string":
                            data[col] = data[col].astype("string")
                        elif to_type == "object":
                            data[col] = data[col].astype("object")
                        else:
                            data[col] = data[col].astype(TYPE_MAP[to_type])

                        self._backend.set_col(col, data[col])

                    except Exception:
                        warnings.warn(
                            f"Cannot convert column '{col}' to {to_type}; leaving unchanged.",
                            UserWarning,
                            stacklevel=2,
                        )

        elif _POLARS_AVAILABLE:
            polars_type_map = {
                "int": pl.Int64,
                "int64": pl.Int64,
                "float": pl.Float64,
                "float64": pl.Float64,
                "number": pl.Float64,
                "string": pl.Utf8,
                "object": pl.Utf8,
            }
            for col in columns:
                if from_type is not None:
                    current_type = str(self._backend.df.schema[col])
                    if from_type not in current_type:
                        continue

                if to_type is not None:
                    try:
                        target = polars_type_map.get(to_type, pl.Utf8)
                        if to_type in ("int", "float", "number"):
                            self._backend.df = self._backend.df.with_columns(
                                pl.col(col).cast(target, strict=False)
                            )
                        else:
                            self._backend.df = self._backend.df.with_columns(
                                pl.col(col).cast(target)
                            )
                    except Exception:
                        warnings.warn(
                            f"Cannot convert column '{col}' to {to_type}; leaving unchanged.",
                            UserWarning,
                            stacklevel=2,
                        )

        self.data = self._backend.df
        return self._backend.df if not self._backend.is_pandas() else data

    # ------------------------------------------------------------------
    # Clean Data
    # ------------------------------------------------------------------

    def clean_data(
        self,
        drop_duplicates: bool = True,
        handle_missing: Union[str, bool] = "auto",
        missing_strategy: str = "mean",
        fill_value: Any = None,
        remove_duplicates: Optional[bool] = None,
        convert_dtypes: bool = False,
        detect_outliers: bool = False,
        remove_outliers: bool = False,
        outlier_method: str = "iqr",
        z_thresh: float = 3.0,
        scale: bool = False,
        scaling_method: str = "standard",
        log_transform: bool = False,
        sqrt_transform: bool = False,
        parse_dates: bool = False,
        drop_columns: Optional[List[str]] = None,
        keep_columns: Optional[List[str]] = None,
        **kwargs,
    ) -> "Preprocessing":
        """
        Comprehensive data cleaning pipeline.

        Parameters
        ----------
        drop_duplicates : bool, default True
            Remove duplicate rows.
        handle_missing : {'auto', 'drop', 'fill', 'skip'} or bool, default 'auto'
            Missing-value handling. 'auto' drops rows with more than
            50% missing values and fills the rest.
        missing_strategy : {'mean', 'median', 'mode', 'constant', 'drop'}, default 'mean'
            Fill strategy for numeric columns (categoricals use the mode).
        fill_value : Any, optional
            Value for ``missing_strategy='constant'``.
        remove_outliers, detect_outliers : bool, default False
            Outlier handling using ``outlier_method`` ('iqr' or 'zscore').
        scale : bool, default False
            Scale numeric columns with ``scaling_method``
            ('standard', 'minmax' or 'robust').
        log_transform, sqrt_transform : bool, default False
            Apply log1p / sqrt to numeric columns (negatives clipped to 0).
        parse_dates : bool, default False
            Try to convert string columns to datetime. Off by default
            because it can misinterpret categorical text columns.
        drop_columns, keep_columns : list of str, optional
            Column filtering applied before everything else.

        Returns
        -------
        Preprocessing
            self, for fluent chaining.
        """

        if remove_duplicates is not None:
            drop_duplicates = remove_duplicates

        if isinstance(handle_missing, bool):
            handle_missing = "auto" if handle_missing else "skip"

        if drop_columns:
            remaining = [c for c in self._backend.columns if c not in drop_columns]
            self.filter_columns(remaining)

        if keep_columns:
            self.filter_columns(keep_columns)

        if drop_duplicates:
            before = self._backend.shape[0]
            if self._backend.is_pandas():
                df = self._backend.df.drop_duplicates()
            else:
                df = self._backend.df.unique()
            self._backend = Backend(df, backend=self._backend.type)
            after = self._backend.shape[0]
            removed = before - after
            if removed:
                logger.info(f"Removed {removed} duplicate row(s)")
            else:
                logger.info("No duplicate rows found")

        if handle_missing not in ("skip", False):
            if handle_missing in ("auto", "drop"):
                cols_count = self._backend.shape[1]
                thresh = int(np.ceil(cols_count / 2))

                if self._backend.is_pandas():
                    df = self._backend.df.dropna(thresh=thresh)
                elif _POLARS_AVAILABLE:
                    null_expr = sum(
                        pl.col(c).is_null().cast(pl.Int32) for c in self._backend.columns
                    )
                    threshold_cols = cols_count / 2
                    df = self._backend.df.filter(null_expr < threshold_cols)
                else:
                    df = self._backend.df

                self._backend = Backend(df, backend=self._backend.type)
                logger.info("Dropped rows with >50% missing values")

            if handle_missing in ("auto", "fill") or missing_strategy in ("mean", "median", "mode", "constant", "drop"):
                for col in self._backend.numeric_columns():
                    if missing_strategy == "drop":
                        if self._backend.is_pandas():
                            self._backend.df = self._backend.df.dropna(subset=[col])
                        elif _POLARS_AVAILABLE:
                            self._backend.df = self._backend.df.drop_nulls(subset=[col])
                        continue
                    if missing_strategy == "median":
                        fill = self._backend.median(col)
                    elif missing_strategy == "constant":
                        fill = fill_value if fill_value is not None else 0
                    else:
                        fill = self._backend.mean(col)
                    self._backend.fillna(value=fill, columns=[col])

                for col in self._backend.categorical_columns():
                    if missing_strategy == "drop":
                        if self._backend.is_pandas():
                            self._backend.df = self._backend.df.dropna(subset=[col])
                        elif _POLARS_AVAILABLE:
                            self._backend.df = self._backend.df.drop_nulls(subset=[col])
                        continue
                    try:
                        mode_val = self._backend.mode(col)
                        if mode_val is not None and not (isinstance(mode_val, np.ndarray) and len(mode_val) == 0):
                            self._backend.fillna(value=mode_val, columns=[col])
                    except Exception:
                        continue
                logger.info("Filled missing values according to strategy")

        for col in self._backend.categorical_columns():
            if self._backend.is_pandas():
                self._backend.df[col] = self._backend.df[col].astype(str).str.strip()
            elif _POLARS_AVAILABLE:
                self._backend.df = self._backend.df.with_columns(
                    pl.col(col).cast(pl.Utf8).str.strip_chars()
                )
        logger.info("Stripped whitespace from string columns")

        if convert_dtypes:
            self.change_dtypes()

        if parse_dates:
            for col in self._backend.columns:
                if self._backend.is_pandas():
                    if self._backend.df[col].dtype == 'object':
                        try:
                            converted = pd.to_datetime(self._backend.df[col])
                            self._backend.df[col] = converted
                            logger.info(f"Converted column '{col}' to datetime")
                        except (ValueError, TypeError):
                            pass
                elif _POLARS_AVAILABLE:
                    if self._backend.df[col].dtype == pl.Utf8:
                        try:
                            self._backend.df = self._backend.df.with_columns(
                                pl.col(col).str.strptime(pl.Datetime, strict=False)
                            )
                            logger.info(f"Converted column '{col}' to datetime")
                        except Exception:
                            pass

        if detect_outliers or remove_outliers:
            for col in self._backend.numeric_columns():
                series = self._backend.col(col)
                if outlier_method == "iqr":
                    q1, q3 = series.quantile(0.25), series.quantile(0.75)
                    iqr = q3 - q1
                    mask = (series >= q1 - 1.5 * iqr) & (series <= q3 + 1.5 * iqr)
                else:
                    z = (series - series.mean()) / (series.std() + 1e-8)
                    mask = z.abs() <= z_thresh
                if remove_outliers:
                    if self._backend.is_pandas():
                        self._backend.filter_by_mask(mask.values)
                    elif _POLARS_AVAILABLE:
                        self._backend.filter_by_mask(mask.to_list())

        if log_transform or sqrt_transform:
            for col in self._backend.numeric_columns():
                arr = self._backend.col_numpy(col)
                if log_transform:
                    arr = np.log1p(np.clip(arr, a_min=0, a_max=None))
                if sqrt_transform:
                    arr = np.sqrt(np.clip(arr, a_min=0, a_max=None))
                self._backend.set_col(col, arr)

        if scale:
            for col in self._backend.numeric_columns():
                series = self._backend.col(col)
                if scaling_method == "minmax":
                    scaled = (series - series.min()) / (series.max() - series.min() + 1e-8)
                elif scaling_method == "robust":
                    med = series.median()
                    iqr = series.quantile(0.75) - series.quantile(0.25)
                    scaled = (series - med) / (iqr + 1e-8)
                else:
                    scaled = (series - series.mean()) / (series.std() + 1e-8)
                self._backend.set_col(col, scaled.values if hasattr(scaled, 'values') else scaled)

        self.data = self._backend.df
        return self

